720p/playlist.m3u8
`;

function rewriteManifest(content, baseUrl, proxyPrefix) {
  const lines = content.split(/\r?\n/);
  const rewritten = lines.map(line => {
    const trimmed = line.trim();
    if (!trimmed) return line;

    // Check for tags with URI="..." attribute
    if (trimmed.startsWith("#EXT-X-MEDIA:") ||
        trimmed.startsWith("#EXT-X-MAP:") ||
        trimmed.startsWith("#EXT-X-KEY:") ||
        trimmed.startsWith("#EXT-X-I-FRAME-STREAM-INF:") ||
        trimmed.startsWith("#EXT-X-PRELOAD-HINT:") ||
        trimmed.startsWith("#EXT-X-RENDITION-REPORT:")) {
      return line.replace(/URI="([^"]+)"/g, (match, rawUri) => {
        const absolute = new URL(rawUri, baseUrl).href;
        return `URI="${proxyPrefix}${encodeURIComponent(absolute)}"`;
      });
    }

    // Comment or header tag that is not a segment line
    if (trimmed.startsWith("#")) {
      return line;
    }

    // Segment or playlist URI line
    const absolute = new URL(trimmed, baseUrl).href;
    return `${proxyPrefix}${encodeURIComponent(absolute)}`;
  });
  return rewritten.join("\n");
}

